import { describe, it, expect } from "vitest";
import { existsSync, readFileSync } from "node:fs";
import { localizedRoutes } from "../i18n/routes";
import { stripMarkdown } from "../utils/text";
import experience from "../data/experience.en.json";
import { brandLogos } from "../data/brandLogos";

// Spot checks for the LLM Markdown twins (llmstxt.org) generated by the
// llms-markdown-sync skill: the twin must exist and must not drift from the
// headings of its English MDX source.

const SITE = "https://davideiken.de";

function sourcePath(route: string) {
  const index = `src/pages${route}/index.mdx`;
  return existsSync(index) ? index : `src/pages${route}.mdx`;
}

const twinPath = (route: string) => `public${route}/index.html.md`;

function normalize(heading: string) {
  return stripMarkdown(
    heading
      .replace(/<br\s*\/?>/g, " ")
      .replace(/<[^>]+>/g, "")
      .replace(/&nbsp;/g, " ")
      .replace(/&ndash;|--/g, "–")
      .replace(/&amp;/g, "&"),
  )
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

function sourceHeadings(mdx: string) {
  const markdown = [...mdx.matchAll(/^\s*##\s+(.+)$/gm)].map((m) => m[1]);
  const html = [...mdx.matchAll(/<h2[^>]*>(.*?)<\/h2>/g)].map((m) => m[1]);
  return [...markdown, ...html].map(normalize);
}

const twinHeadings = (md: string) =>
  [...md.matchAll(/^##\s+(.+)$/gm)].map((m) => normalize(m[1]));

const pages = localizedRoutes
  .map(({ en }) => ({ route: en, source: sourcePath(en) }))
  .filter(({ source }) => {
    const mdx = readFileSync(source, "utf8");
    return !/^noindex:\s*true/m.test(mdx);
  });

describe("LLM Markdown twins", () => {
  it.each(pages)("$route has a twin", ({ route }) => {
    expect(existsSync(twinPath(route))).toBe(true);
  });

  it.each(pages)("$route twin starts with H1 and summary", ({ route }) => {
    const lines = readFileSync(twinPath(route), "utf8")
      .split("\n")
      .filter((line) => line.trim() !== "");
    expect(lines[0]).toMatch(/^# \S/);
    expect(lines[1]).toMatch(/^> \S/);
    expect(lines.filter((line) => /^# /.test(line))).toHaveLength(1);
  });

  it.each(pages)("$route twin contains every H2", ({ route, source }) => {
    const expected = sourceHeadings(readFileSync(source, "utf8"));
    const actual = twinHeadings(readFileSync(twinPath(route), "utf8"));
    for (const heading of expected) {
      expect(actual).toContain(heading);
    }
  });

  it("experience twin lists the timeline", () => {
    const md = readFileSync(twinPath("/en/experience"), "utf8");
    for (const entry of [experience[0], experience.at(-1)!]) {
      expect(md).toContain(entry.title);
    }
  });

  it("home twin lists every brand of the logo grid", () => {
    const md = readFileSync(twinPath("/en"), "utf8");
    for (const { name } of brandLogos) {
      expect(md).toContain(name);
    }
  });

  it("llms.txt links only to existing twins", () => {
    const txt = readFileSync("public/llms.txt", "utf8");
    const links = [...txt.matchAll(/\((https:\/\/davideiken\.de[^)]*\.md)\)/g)];
    expect(links.length).toBeGreaterThan(0);
    for (const [, url] of links) {
      expect(existsSync(`public${url.slice(SITE.length)}`), url).toBe(true);
    }
  });
});
